from httpbin.core import app
client = app.test_client()

def test_post_form_data_returns_200_with_all_keys():
    r = client.post('/post', data={'key': 'value'},
                    content_type='application/x-www-form-urlencoded')
    assert r.status_code == 200
    body = r.get_json()
    expected_keys = {'url', 'args', 'headers', 'form', 'data', 'files', 'json', 'origin'}
    assert set(body.keys()) == expected_keys
    assert body['form'] == {'key': 'value'}
    assert body['data'] == ''
    assert body['json'] is None
    assert body['args'] == {}
    assert body['files'] == {}

test_post_form_data_returns_200_with_all_keys()

import json as _json
from httpbin.core import app
client = app.test_client()

def test_post_json_body_reflected_in_json_field():
    payload = {'alpha': 1, 'beta': 'hello'}
    r = client.post('/post',
                    data=_json.dumps(payload),
                    content_type='application/json')
    assert r.status_code == 200
    body = r.get_json()
    assert body['json'] == {'alpha': 1, 'beta': 'hello'}
    assert body['form'] == {}
    assert body['files'] == {}
    assert body['args'] == {}
    assert 'url' in body
    assert 'headers' in body
    assert 'origin' in body

test_post_json_body_reflected_in_json_field()

